#ifndef KERNEL_H
#define KERNEL_H

#include "ap_fixed.h"
#include "ap_int.h"

// ---------------------------------------------------------------------------
// Type definitions derived from params.yaml
// bits_per_component = bits + signed
// ap_fixed<bits_per_component, bits_per_component - fraction>
// ---------------------------------------------------------------------------

// in0: A, complex, bits=22, signed=1, fraction=0
// bits_per_component = 23, integer_bits = 23 - 0 = 23
typedef ap_fixed<23, 23> in0_scalar_t;
struct in0_t { in0_scalar_t re, im; };
#define DIM_IN0_0 10
#define DIM_IN0_1 10

// in1: max_iter, real, bits=16, signed=0, fraction=0
// bits_per_component = 16, integer_bits = 16 - 0 = 16
typedef ap_fixed<16, 16> in1_t;

// out0: eigenvalues, complex, bits=22, signed=1, fraction=0
// bits_per_component = 23, integer_bits = 23 - 0 = 23
typedef ap_fixed<23, 23> out0_scalar_t;
struct out0_t { out0_scalar_t re, im; };
#define DIM_OUT0_0 10

// out1: eigenvectors, complex, bits=22, signed=1, fraction=20
// bits_per_component = 23, integer_bits = 23 - 20 = 3
typedef ap_fixed<23, 3> out1_scalar_t;
struct out1_t { out1_scalar_t re, im; };
#define DIM_OUT1_0 10
#define DIM_OUT1_1 10

// out2: ite, real, bits=16, signed=0, fraction=0
// bits_per_component = 16, integer_bits = 16 - 0 = 16
typedef ap_fixed<16, 16> out2_t;

// ---------------------------------------------------------------------------
// Top-level function declaration
// ---------------------------------------------------------------------------
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2
);

#endif // KERNEL_H

