#include "kernel.h"
#include "ap_fixed.h"
#include "ap_int.h"

// ---------------------------------------------------------------------------
// Internal high-precision fixed-point types for intermediate arithmetic
// We use wide ap_fixed types to keep precision through trig/complex ops.
// Format: <48,24> gives 24 integer bits and 24 fractional bits.
// ---------------------------------------------------------------------------
typedef ap_fixed<48, 24> calc_t;

// ---------------------------------------------------------------------------
// Compile-time constants
// ---------------------------------------------------------------------------
static const int N = 10;

// Convergence threshold: 1e-8 ~ 2^-26.57, represented in calc_t fraction bits
// We use 0 as threshold since we cannot use double; approximate with small fixed value
// 1e-8 in Q24.24: 1e-8 * 2^24 ≈ 167.77 → value ≈ 167 ulps of calc_t
// In ap_fixed<48,24> the LSB is 2^-24 ≈ 5.96e-8, so threshold ~2 LSBs
static const calc_t THRESHOLD = calc_t(1) >> 23; // ≈ 1.19e-7, close to 1e-8

// ---------------------------------------------------------------------------
// Fixed-point approximation utilities (no float/double)
// ---------------------------------------------------------------------------

// Absolute value
static calc_t fp_abs(calc_t x) {
    return (x < calc_t(0)) ? calc_t(-x) : x;
}

// Square root via Newton-Raphson (integer seed)
static calc_t fp_sqrt(calc_t x) {
    #pragma HLS INLINE
    if (x <= calc_t(0)) return calc_t(0);
    // Initial guess: shift right by half the bit width
    calc_t guess = x >> 1;
    if (guess == calc_t(0)) guess = calc_t(1) >> 12;
    // 16 Newton-Raphson iterations: g = (g + x/g) / 2
    for (int i = 0; i < 16; i++) {
        #pragma HLS UNROLL
        if (guess <= calc_t(0)) break;
        calc_t next = (guess + x / guess) >> 1;
        guess = next;
    }
    return guess;
}

// Magnitude of complex number: sqrt(re^2 + im^2)
static calc_t fp_cabs(calc_t re, calc_t im) {
    #pragma HLS INLINE
    return fp_sqrt(re * re + im * im);
}

// atan2 approximation using polynomial series
// Returns angle in range [-pi/2, pi/2] for atan(y/x) where we only need atan
// We implement atan(z) for z = y/x
// Minimax polynomial: atan(z) ≈ z*(a0 + z^2*(a1 + z^2*(a2 + z^2*a3)))
// Valid for |z| <= 1; use identity atan(z) = pi/2 - atan(1/z) for |z| > 1
static calc_t fp_atan(calc_t z) {
    #pragma HLS INLINE
    // Constants (Horner form coefficients for atan, degree-7 minimax)
    // atan(z) ≈ z - z^3/3 + z^5/5 - z^7/7 (Taylor; accurate near 0)
    // For better range, use minimax:
    // a0=0.9999993, a1=-0.3332995, a2=0.1993700, a3=-0.1387790 ... 
    // We use 5-term Taylor since we normalize to |z|<=1
    static const calc_t ONE    = calc_t(1);
    static const calc_t PI_2   = calc_t(1) + (calc_t(1) >> 1) + (calc_t(1) >> 3) +
                                  (calc_t(1) >> 4) + (calc_t(1) >> 6); // ~1.5708
    bool neg = (z < calc_t(0));
    bool inv = false;
    calc_t zz = neg ? calc_t(-z) : z;
    if (zz > ONE) {
        inv = true;
        zz = ONE / zz;
    }
    // Taylor: atan(z) = z - z^3/3 + z^5/5 - z^7/7 + z^9/9 - z^11/11
    calc_t z2 = zz * zz;
    calc_t result = zz * (ONE - z2 * ((ONE / calc_t(3)) - z2 * ((ONE / calc_t(5)) -
                   z2 * ((ONE / calc_t(7)) - z2 * ((ONE / calc_t(9)) -
                   z2 * (ONE / calc_t(11)))))));
    if (inv) {
        result = PI_2 - result;
    }
    if (neg) result = -result;
    return result;
}

// atan2(y, x) full quadrant
static calc_t fp_atan2(calc_t y, calc_t x) {
    #pragma HLS INLINE
    // PI approximation: 3.14159265 ≈ 3 + 1/8 + 1/256 + ...
    // Use: pi ≈ 3.14159265358979
    static const calc_t PI = calc_t(3) + (calc_t(1) >> 3) + (calc_t(1) >> 7) +
                              (calc_t(1) >> 9) + (calc_t(1) >> 13) +
                              (calc_t(1) >> 16) + (calc_t(1) >> 18); // ~3.14159
    static const calc_t PI_2 = calc_t(1) + (calc_t(1) >> 1) + (calc_t(1) >> 3) +
                                (calc_t(1) >> 4) + (calc_t(1) >> 6) +
                                (calc_t(1) >> 7) + (calc_t(1) >> 9) +
                                (calc_t(1) >> 17); // ~1.5708
    if (x == calc_t(0)) {
        if (y >= calc_t(0)) return PI_2;
        else return -PI_2;
    }
    calc_t angle = fp_atan(y / x);
    if (x < calc_t(0)) {
        if (y >= calc_t(0)) angle = angle + PI;
        else                angle = angle - PI;
    }
    return angle;
}

// cos approximation: Taylor series around 0
// cos(x) = 1 - x^2/2! + x^4/4! - x^6/6! + x^8/8!
static calc_t fp_cos(calc_t x) {
    #pragma HLS INLINE
    // Reduce to [-pi, pi] — not done here since theta is already small
    calc_t x2 = x * x;
    calc_t result = calc_t(1)
                    - x2 * ((calc_t(1) / calc_t(2))
                    - x2 * ((calc_t(1) / calc_t(24))
                    - x2 * ((calc_t(1) / calc_t(720))
                    - x2 * (calc_t(1) / calc_t(40320)))));
    return result;
}

// sin approximation: Taylor series
// sin(x) = x - x^3/3! + x^5/5! - x^7/7! + x^9/9!
static calc_t fp_sin(calc_t x) {
    #pragma HLS INLINE
    calc_t x2 = x * x;
    calc_t result = x * (calc_t(1)
                    - x2 * ((calc_t(1) / calc_t(6))
                    - x2 * ((calc_t(1) / calc_t(120))
                    - x2 * ((calc_t(1) / calc_t(5040))
                    - x2 * (calc_t(1) / calc_t(362880))))));
    return result;
}

// ---------------------------------------------------------------------------
// Complex multiply: (a+jb)*(c+jd) = (ac-bd) + j(ad+bc)
// ---------------------------------------------------------------------------
static void cmul(calc_t ar, calc_t ai, calc_t br, calc_t bi,
                 calc_t &rr, calc_t &ri) {
    #pragma HLS INLINE
    rr = ar * br - ai * bi;
    ri = ar * bi + ai * br;
}

// ---------------------------------------------------------------------------
// Top-level kernel
// ---------------------------------------------------------------------------
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2
)
{
    #pragma HLS INTERFACE ap_ctrl_hs port=return
    #pragma HLS PIPELINE off

    // -----------------------------------------------------------------------
    // Copy input matrix A into local working arrays (real and imag parts)
    // -----------------------------------------------------------------------
    calc_t A_re[N][N], A_im[N][N];
    calc_t V_re[N][N], V_im[N][N];

    INIT_A:
    for (int i = 0; i < N; i++) {
        #pragma HLS LOOP_TRIPCOUNT min=10 max=10
        for (int j = 0; j < N; j++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            A_re[i][j] = calc_t(in0[i][j].re);
            A_im[i][j] = calc_t(in0[i][j].im);
            // V = eye(N): identity matrix (real)
            V_re[i][j] = (i == j) ? calc_t(1) : calc_t(0);
            V_im[i][j] = calc_t(0);
        }
    }

    int max_iter_val = (int)in1;
    int last_z = 0;

    // -----------------------------------------------------------------------
    // Jacobi iteration loop
    // -----------------------------------------------------------------------
    OUTER:
    for (int z = 0; z < 32768; z++) {
        #pragma HLS LOOP_TRIPCOUNT min=1 max=1000
        if (z >= max_iter_val) {
            last_z = z;
            break;
        }

        // Find (p, q) with largest |A[i,j]|, i < j
        calc_t off_diag_max = calc_t(0);
        int p = 0, q = 1;

        FIND_PQ_I:
        for (int i = 0; i < N; i++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            FIND_PQ_J:
            for (int j = i + 1; j < N; j++) {
                #pragma HLS LOOP_TRIPCOUNT min=1 max=9
                calc_t mag = fp_cabs(A_re[i][j], A_im[i][j]);
                if (mag > off_diag_max) {
                    off_diag_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        // Convergence check
        if (off_diag_max < THRESHOLD) {
            last_z = z;
            break;
        }

        last_z = z;

        // Extract relevant elements
        calc_t a_pp_re = A_re[p][p], a_pp_im = A_im[p][p];
        calc_t a_qq_re = A_re[q][q], a_qq_im = A_im[q][q];
        calc_t a_pq_re = A_re[p][q], a_pq_im = A_im[p][q];

        // |a_pq|
        calc_t abs_apq = fp_cabs(a_pq_re, a_pq_im);

        // theta = 0.5 * atan(2*|a_pq| / (a_pp - a_qq))
        // Note: a_pp and a_qq are real (diagonal of Hermitian matrix)
        calc_t denom = a_pp_re - a_qq_re;
        calc_t theta;
        if (denom == calc_t(0)) {
            // atan(inf) = pi/2; theta = pi/4
            static const calc_t PI_4 = calc_t(0) + (calc_t(1) >> 2) +
                                       (calc_t(1) >> 5) + (calc_t(1) >> 7) +
                                       (calc_t(1) >> 10) + (calc_t(1) >> 13) +
                                       (calc_t(1) >> 16); // ~0.7854
            theta = PI_4;
        } else {
            theta = fp_atan((calc_t(2) * abs_apq) / denom) >> 1;
        }

        // phi = -angle(a_pq) = -atan2(im(a_pq), re(a_pq))
        calc_t phi = -fp_atan2(a_pq_im, a_pq_re);

        // Precompute trig values
        calc_t cos_t = fp_cos(theta);
        calc_t sin_t = fp_sin(theta);
        calc_t neg_cos_t = -cos_t;

        // exp(-j*phi) = cos(phi) - j*sin(phi)
        // exp(+j*phi) = cos(phi) + j*sin(phi)
        calc_t cos_phi = fp_cos(phi);
        calc_t sin_phi = fp_sin(phi);

        // U[p][p] = cos(theta),                   U_pp = (cos_t, 0)
        // U[p][q] = sin(theta)*exp(-j*phi),        U_pq = (sin_t*cos_phi, -sin_t*sin_phi)
        // U[q][p] = sin(theta)*exp(+j*phi),        U_qp = (sin_t*cos_phi, +sin_t*sin_phi)
        // U[q][q] = -cos(theta),                   U_qq = (-cos_t, 0)
        calc_t U_pp_re = cos_t,                 U_pp_im = calc_t(0);
        calc_t U_pq_re = sin_t * cos_phi,       U_pq_im = -(sin_t * sin_phi);
        calc_t U_qp_re = sin_t * cos_phi,       U_qp_im =  sin_t * sin_phi;
        calc_t U_qq_re = neg_cos_t,             U_qq_im = calc_t(0);

        // -----------------------------------------------------------------------
        // Compute A' = U^H * A * U
        // U^H = conj(U)^T:
        //   U^H[p][p] = conj(U[p][p]) = (cos_t, 0)
        //   U^H[p][q] = conj(U[q][p]) = (sin_t*cos_phi, -sin_t*sin_phi)
        //   U^H[q][p] = conj(U[p][q]) = (sin_t*cos_phi, +sin_t*sin_phi)
        //   U^H[q][q] = conj(U[q][q]) = (-cos_t, 0)
        // Note: U^H[p][p]=U[p][p], U^H[p][q]=conj(U[q][p])=conj(U_qp)
        //       U^H[q][p]=conj(U[p][q])=conj(U_pq), U^H[q][q]=U[q][q]
        // -----------------------------------------------------------------------

        // Step 1: B = A * U  (only columns p and q change)
        calc_t B_re[N][N], B_im[N][N];

        COPY_B:
        for (int i = 0; i < N; i++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            for (int j = 0; j < N; j++) {
                #pragma HLS LOOP_TRIPCOUNT min=10 max=10
                B_re[i][j] = A_re[i][j];
                B_im[i][j] = A_im[i][j];
            }
        }

        // Update columns p and q of B
        MATVEC_B:
        for (int i = 0; i < N; i++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            calc_t aip_re = A_re[i][p], aip_im = A_im[i][p];
            calc_t aiq_re = A_re[i][q], aiq_im = A_im[i][q];

            // B[i][p] = A[i][p]*U[p][p] + A[i][q]*U[q][p]
            calc_t t1r, t1i, t2r, t2i;
            cmul(aip_re, aip_im, U_pp_re, U_pp_im, t1r, t1i);
            cmul(aiq_re, aiq_im, U_qp_re, U_qp_im, t2r, t2i);
            B_re[i][p] = t1r + t2r;
            B_im[i][p] = t1i + t2i;

            // B[i][q] = A[i][p]*U[p][q] + A[i][q]*U[q][q]
            cmul(aip_re, aip_im, U_pq_re, U_pq_im, t1r, t1i);
            cmul(aiq_re, aiq_im, U_qq_re, U_qq_im, t2r, t2i);
            B_re[i][q] = t1r + t2r;
            B_im[i][q] = t1i + t2i;
        }

        // Step 2: A' = U^H * B  (only rows p and q change)
        // U^H non-trivial rows: row p, row q
        // U^H[p][p] = conj(U_pp) = (cos_t, 0)
        // U^H[p][q] = conj(U_qp) = (U_qp_re, -U_qp_im)
        // U^H[q][p] = conj(U_pq) = (U_pq_re, -U_pq_im)
        // U^H[q][q] = conj(U_qq) = (neg_cos_t, 0)
        calc_t UH_pp_re = cos_t,               UH_pp_im = calc_t(0);
        calc_t UH_pq_re = U_qp_re,             UH_pq_im = -U_qp_im;
        calc_t UH_qp_re = U_pq_re,             UH_qp_im = -U_pq_im;
        calc_t UH_qq_re = neg_cos_t,           UH_qq_im = calc_t(0);

        // Copy B into A (all rows unchanged except p and q)
        UPDATE_A:
        for (int j = 0; j < N; j++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            calc_t bpj_re = B_re[p][j], bpj_im = B_im[p][j];
            calc_t bqj_re = B_re[q][j], bqj_im = B_im[q][j];

            // A'[p][j] = UH[p][p]*B[p][j] + UH[p][q]*B[q][j]
            calc_t t1r, t1i, t2r, t2i;
            cmul(UH_pp_re, UH_pp_im, bpj_re, bpj_im, t1r, t1i);
            cmul(UH_pq_re, UH_pq_im, bqj_re, bqj_im, t2r, t2i);
            A_re[p][j] = t1r + t2r;
            A_im[p][j] = t1i + t2i;

            // A'[q][j] = UH[q][p]*B[p][j] + UH[q][q]*B[q][j]
            cmul(UH_qp_re, UH_qp_im, bpj_re, bpj_im, t1r, t1i);
            cmul(UH_qq_re, UH_qq_im, bqj_re, bqj_im, t2r, t2i);
            A_re[q][j] = t1r + t2r;
            A_im[q][j] = t1i + t2i;
        }

        // Copy unchanged rows from B
        COPY_ROWS:
        for (int i = 0; i < N; i++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            if (i != p && i != q) {
                for (int j = 0; j < N; j++) {
                    #pragma HLS LOOP_TRIPCOUNT min=10 max=10
                    A_re[i][j] = B_re[i][j];
                    A_im[i][j] = B_im[i][j];
                }
            }
        }

        // Explicitly zero out (p,q) and (q,p)
        A_re[p][q] = calc_t(0); A_im[p][q] = calc_t(0);
        A_re[q][p] = calc_t(0); A_im[q][p] = calc_t(0);

        // -----------------------------------------------------------------------
        // Update V = V * U  (all rows of V, only columns p and q change)
        // -----------------------------------------------------------------------
        UPDATE_V:
        for (int i = 0; i < N; i++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            calc_t vip_re = V_re[i][p], vip_im = V_im[i][p];
            calc_t viq_re = V_re[i][q], viq_im = V_im[i][q];

            calc_t t1r, t1i, t2r, t2i;

            // V'[i][p] = V[i][p]*U[p][p] + V[i][q]*U[q][p]
            cmul(vip_re, vip_im, U_pp_re, U_pp_im, t1r, t1i);
            cmul(viq_re, viq_im, U_qp_re, U_qp_im, t2r, t2i);
            V_re[i][p] = t1r + t2r;
            V_im[i][p] = t1i + t2i;

            // V'[i][q] = V[i][p]*U[p][q] + V[i][q]*U[q][q]
            cmul(vip_re, vip_im, U_pq_re, U_pq_im, t1r, t1i);
            cmul(viq_re, viq_im, U_qq_re, U_qq_im, t2r, t2i);
            V_re[i][q] = t1r + t2r;
            V_im[i][q] = t1i + t2i;
        }
    }

    // -----------------------------------------------------------------------
    // Write outputs
    // -----------------------------------------------------------------------

    // out0: diagonal of A (eigenvalues)
    WRITE_EVALS:
    for (int i = 0; i < N; i++) {
        #pragma HLS LOOP_TRIPCOUNT min=10 max=10
        out0[i].re = out0_scalar_t(A_re[i][i]);
        out0[i].im = out0_scalar_t(A_im[i][i]);
    }

    // out1: V (eigenvectors)
    WRITE_EVECS:
    for (int i = 0; i < N; i++) {
        #pragma HLS LOOP_TRIPCOUNT min=10 max=10
        for (int j = 0; j < N; j++) {
            #pragma HLS LOOP_TRIPCOUNT min=10 max=10
            out1[i][j].re = out1_scalar_t(V_re[i][j]);
            out1[i][j].im = out1_scalar_t(V_im[i][j]);
        }
    }

    // out2: iteration count (z at break/end)
    *out2 = out2_t(last_z);
}
